      NOW
    )
    expect(one.detail).toBe('expires in 1 day')
    const today = upstreamHealth(
      { connected: true, needsReauth: false, authExpiresAt: NOW + 3600, authExpiresSource: 'provider' },
      NOW
    )
    expect(today.detail).toBe('expires today')
